initJs:
function(container, apiUrl, tables) {
  let currentOrderData = [];
  let storesData = [];
  let productsData = [];
  let demandForecastData = [];
  let inventoryData = [];

  // 今日の日付を設定
  const today = new Date().toISOString().split('T')[0];
  container.querySelector('#order-date').value = today;

  // エラーメッセージ表示関数
  function showError(message) {
    const errorDiv = container.querySelector('#error-message');
    errorDiv.textContent = message;
    errorDiv.classList.remove('hidden');
    setTimeout(() => errorDiv.classList.add('hidden'), 5000);
  }

  // 発注テーブル再描画関数
  function renderOrderTable(orderItems) {
    const tbody = container.querySelector('#order-table-body');

    if (!orderItems || orderItems.length === 0) {
      tbody.innerHTML = '<tr><td colspan="9" style="text-align: center; padding: 40px; color: var(--text-muted);">データがありません</td></tr>';
      updateTotalAmount();
      return;
    }

    tbody.innerHTML = orderItems.map(item => `
      <tr data-product-id="${item.productId}">
        <td>
          <input type="checkbox" class="product-checkbox" data-product-id="${item.productId}">
        </td>
        <td>${item.productCode || ''}</td>
        <td>${item.productName || ''}</td>
        <td style="text-align: right;">${item.forecastQuantity || 0}</td>
        <td style="text-align: right;">${item.recommendedQuantity || 0}</td>
        <td style="text-align: right;">${item.currentStock || 0}</td>
        <td>
          <input type="number" class="input quantity-input" data-product-id="${item.productId}" 
                 value="${item.orderQuantity || 0}" min="0" max="99999" style="width: 100px;">
        </td>
        <td style="text-align: right;">¥${(item.unitPrice || 0).toLocaleString()}</td>
        <td style="text-align: right;" class="order-amount" data-product-id="${item.productId}">
          ¥${((item.orderQuantity || 0) * (item.unitPrice || 0)).toLocaleString()}
        </td>
      </tr>
    `).join('');

    updateTotalAmount();
  }

  // 合計金額更新
  function updateTotalAmount() {
    const checkboxes = container.querySelectorAll('.product-checkbox:checked');
    const selectedCountEl = container.querySelector('#selected-count');
    const totalAmountEl = container.querySelector('#total-amount');
    const bulkOrderBtn = container.querySelector('#btn-bulk-order');

    let totalAmount = 0;
    let selectedCount = 0;

    checkboxes.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`.quantity-input[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 0;
      const item = currentOrderData.find(d => d.productId === productId);
      if (item && quantity > 0) {
        totalAmount += quantity * (item.unitPrice || 0);
        selectedCount++;
      }
    });

    selectedCountEl.textContent = selectedCount;
    totalAmountEl.textContent = `¥${totalAmount.toLocaleString()}`;
    bulkOrderBtn.disabled = selectedCount === 0;
  }

  // 発注データ生成
  function generateOrderData(storeId, orderDate) {
    if (!storeId) return [];

    const orderItems = [];

    // 需要予測データから発注対象商品を抽出
    demandForecastData.forEach(forecast => {
      if (forecast.店舗ID !== storeId) return;

      const product = productsData.find(p => p.商品ID === forecast.商品ID);
      if (!product || !product.有効フラグ) return;

      // 現在在庫を取得（仮想データ）
      const currentStock = Math.floor(Math.random() * 50);

      const orderItem = {
        productId: product.商品ID,
        productCode: product.商品コード,
        productName: product.商品名,
        forecastQuantity: forecast.予測数量 || 0,
        recommendedQuantity: forecast.推奨発注数量 || 0,
        currentStock: currentStock,
        orderQuantity: forecast.推奨発注数量 || 0,
        unitPrice: product.単価 || 0
      };

      orderItems.push(orderItem);
    });

    return orderItems;
  }

  // 初期データ読み込み
  async function loadInitialData() {
    try {
      // 店舗データ読み込み
      const stores = await window.aivicApi.list(1); // 店舗マスタ
      if (stores) {
        storesData = stores;
        const storeSelect = container.querySelector('#store-select');
        storeSelect.innerHTML = '<option value="">店舗を選択してください</option>' +
          stores.filter(s => s.有効フラグ).map(store => 
            `<option value="${store.店舗ID}">${store.店舗名}</option>`
          ).join('');
      }

      // 商品データ読み込み
      const products = await window.aivicApi.list(2); // 商品マスタ
      if (products) {
        productsData = products;

        // カテゴリフィルター設定（仮想カテゴリ）
        const categories = ['食品', '日用品', '衣料品', '家電', 'その他'];
        const categorySelect = container.querySelector('#category-filter');
        categorySelect.innerHTML = '<option value="">全てのカテゴリ</option>' +
          categories.map(cat => `<option value="${cat}">${cat}</option>`).join('');
      }

      // 需要予測データ読み込み
      const forecasts = await window.aivicApi.list(8); // 需要予測結果
      if (forecasts) {
        demandForecastData = forecasts;
      }

    } catch (error) {
      console.error('データ読み込みエラー:', error);
      showError('データの読み込みに失敗しました');
    }
  }

  // 店舗選択変更イベント
  container.querySelector('#store-select').addEventListener('change', function() {
    const storeId = this.value;
    const orderDate = container.querySelector('#order-date').value;

    if (storeId && orderDate) {
      currentOrderData = generateOrderData(storeId, orderDate);
      renderOrderTable(currentOrderData);
    } else {
      renderOrderTable([]);
    }
  });

  // 発注日付変更イベント
  container.querySelector('#order-date').addEventListener('change', function() {
    const orderDate = this.value;
    const today = new Date().toISOString().split('T')[0];

    if (orderDate < today) {
      showError('発注日付は本日以降の日付を選択してください');
      this.value = today;
      return;
    }

    const storeId = container.querySelector('#store-select').value;
    if (storeId && orderDate) {
      currentOrderData = generateOrderData(storeId, orderDate);
      renderOrderTable(currentOrderData);
    }
  });

  // カテゴリフィルター変更イベント
  container.querySelector('#category-filter').addEventListener('change', function() {
    const category = this.value;
    const storeId = container.querySelector('#store-select').value;

    if (!storeId) return;

    let filteredData = currentOrderData;
    if (category) {
      // 仮想的なカテゴリフィルタリング
      filteredData = currentOrderData.filter(item => {
        const productName = item.productName.toLowerCase();
        switch(category) {
          case '食品': return productName.includes('食') || productName.includes('パン') || productName.includes('米');
          case '日用品': return productName.includes('洗剤') || productName.includes('石鹸') || productName.includes('タオル');
          case '衣料品': return productName.includes('服') || productName.includes('シャツ') || productName.includes('靴');
          case '家電': return productName.includes('電') || productName.includes('機器');
          default: return true;
        }
      });
    }

    renderOrderTable(filteredData);
  });

  // 表示更新ボタン
  container.querySelector('#btn-filter').addEventListener('click', function() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (!orderDate) {
      showError('発注日付を選択してください');
      return;
    }

    currentOrderData = generateOrderData(storeId, orderDate);

    // カテゴリフィルターを適用
    const category = container.querySelector('#category-filter').value;
    let filteredData = currentOrderData;
    if (category) {
      filteredData = currentOrderData.filter(item => {
        const productName = item.productName.toLowerCase();
        switch(category) {
          case '食品': return productName.includes('食') || productName.includes('パン') || productName.includes('米');
          case '日用品': return productName.includes('洗剤') || productName.includes('石鹸') || productName.includes('タオル');
          case '衣料品': return productName.includes('服') || productName.includes('シャツ') || productName.includes('靴');
          case '家電': return productName.includes('電') || productName.includes('機器');
          default: return true;
        }
      });
    }

    renderOrderTable(filteredData);
  });

  // 全選択チェックボックス
  container.querySelector('#select-all').addEventListener('change', function() {
    const checkboxes = container.querySelectorAll('.product-checkbox');
    checkboxes.forEach(cb => cb.checked = this.checked);
    updateTotalAmount();
  });

  // 数量入力・チェックボックス変更イベント（イベントデリゲーション）
  container.addEventListener('input', function(e) {
    if (e.target.classList.contains('quantity-input')) {
      const productId = e.target.dataset.productId;
      const quantity = parseInt(e.target.value) || 0;

      // バリデーション
      if (quantity < 0) {
        showError('発注数量は0以上の値を入力してください');
        e.target.value = 0;
        return;
      }

      if (quantity > 99999) {
        showError('発注数量は99999以下で入力してください');
        e.target.value = 99999;
        return;
      }

      if (e.target.value.includes('.')) {
        showError('発注数量は整数で入力してください');
        e.target.value = Math.floor(quantity);
        return;
      }

      // 金額更新
      const item = currentOrderData.find(d => d.productId === productId);
      if (item) {
        const amount = quantity * (item.unitPrice || 0);
        const amountCell = container.querySelector(`.order-amount[data-product-id="${productId}"]`);
        if (amountCell) {
          amountCell.textContent = `¥${amount.toLocaleString()}`;
        }
      }

      updateTotalAmount();
    }
  });

  container.addEventListener('change', function(e) {
    if (e.target.classList.contains('product-checkbox')) {
      updateTotalAmount();
    }
  });

  // まとめて発注実行ボタン
  container.querySelector('#btn-bulk-order').addEventListener('click', function() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    const selectedItems = [];
    const checkboxes = container.querySelectorAll('.product-checkbox:checked');

    checkboxes.forEach(checkbox => {
      const productId = checkbox.dataset.productId;
      const quantityInput = container.querySelector(`.quantity-input[data-product-id="${productId}"]`);
      const quantity = parseInt(quantityInput.value) || 0;

      if (quantity <= 0) {
        showError('発注数量は1以上の値を入力してください');
        return;
      }

      const item = currentOrderData.find(d => d.productId === productId);
      if (item) {
        selectedItems.push({
          ...item,
          orderQuantity: quantity
        });
      }
    });

    if (selectedItems.length === 0) {
      showError('発注する商品を選択してください');
      return;
    }

    showOrderConfirmDialog(selectedItems, storeId, orderDate);
  });

  // 推奨数量で一括発注ボタン
  container.querySelector('#btn-recommended-order').addEventListener('click', function() {
    const storeId = container.querySelector('#store-select').value;
    const orderDate = container.querySelector('#order-date').value;

    if (!storeId) {
      showError('店舗を選択してください');
      return;
    }

    if (currentOrderData.length === 0) {
      showError('発注対象商品がありません');
      return;
    }

    // 推奨数量が0より大きい商品のみを対象
    const recommendedItems = currentOrderData.filter(item => (item.recommendedQuantity || 0) > 0);

    if (recommendedItems.length === 0) {
      showError('推奨発注数量が設定された商品がありません');
      return;
    }

    showOrderConfirmDialog(recommendedItems, storeId, orderDate);
  });

  // 発注確認ダイアログ表示
  function showOrderConfirmDialog(orderItems, storeId, orderDate) {
    const dialog = container.querySelector('#order-confirm-dialog');
    const content = container.querySelector('#order-confirm-content');

    const store = storesData.find(s => s.店舗ID === storeId);
    const storeName = store ? store.店舗名 : '不明な店舗';

    let totalAmount = 0;
    const itemsHtml = orderItems.map(item => {
      const amount = (item.orderQuantity || item.recommendedQuantity || 0) * (item.unitPrice || 0);
      totalAmount += amount;
      return `
        <tr>
          <td>${item.productCode}</td>
          <td>${item.productName}</td>
          <td style="text-align: right;">${item.orderQuantity || item.recommendedQuantity || 0}</td>
          <td style="text-align: right;">¥${(item.unitPrice || 0).toLocaleString()}</td>
          <td style="text-align: right;">¥${amount.toLocaleString()}</td>
        </tr>
      `;
    }).join('');

    content.innerHTML = `
      <div style="margin-bottom: 16px;">
        <p><strong>店舗:</strong> ${storeName}</p>
        <p><strong>発注日:</strong> ${orderDate}</p>
        <p><strong>発注商品数:</strong> ${orderItems.length}件</p>
      </div>
      <div class="table-wrap" style="max-height: 300px; overflow-y: auto;">
        <table>
          <thead>
            <tr>
              <th>商品コード</th>
              <th>商品名</th>
              <th>数量</th>
              <th>単価</th>
              <th>金額</th>
            </tr>
          </thead>
          <tbody>
            ${itemsHtml}
          </tbody>
        </table>
      </div>
      <div style="margin-top: 16px; text-align: right; font-size: 18px; font-weight: bold;">
        合計金額: <span style="color: var(--primary);">¥${totalAmount.toLocaleString()}</span>
      </div>
    `;

    dialog.classList.remove('hidden');

    // 発注実行ボタンにデータを保存
    container.querySelector('#btn-execute-order').orderData = {
      orderItems,
      storeId,
      orderDate,
      totalAmount
    };
  }

  // 発注確認ダイアログのキャンセル
  container.querySelector('#btn-cancel-order').addEventListener('click', function() {
    container.querySelector('#order-confirm-dialog').classList.add('hidden');
  });

  // 発注実行
  container.querySelector('#btn-execute-order').addEventListener('click', async function() {
    const orderData = this.orderData;
    if (!orderData) return;

    try {
      // 各商品の発注データを保存
      for (const item of orderData.orderItems) {
        const orderRecord = {
          店舗ID: orderData.storeId,
          商品ID: item.productId,
          発注日: orderData.orderDate + 'T00:00:00Z',
          納期予定日: new Date(Date.now() + 3 * 24 * 60 * 60 * 1000).toISOString(), // 3日後
          発注数量: item.orderQuantity || item.recommendedQuantity || 0,
          予測数量: item.forecastQuantity || 0,
          発注単価: item.unitPrice || 0,
          発注金額: (item.orderQuantity || item.recommendedQuantity || 0) * (item.unitPrice || 0),
          発注方法: item.orderQuantity ? 'AI推奨修正' : 'AI推奨採用',
          発注ステータス: '発注済',
          仕入先ID: 'supplier-001', // 仮の仕入先ID
          自動発注フラグ: false,
          作成日時: new Date().toISOString(),
          更新日時: new Date().toISOString(),
          作成者ID: 'current-user-id', // 現在のユーザーID
          更新者ID: 'current-user-id'
        };

        await window.aivicApi.save(9, orderRecord); // 発注データテーブル
      }

      // ダイアログを閉じる
      container.querySelector('#order-confirm-dialog').classList.add('hidden');

      // 成功メッセージ表示
      alert(`発注が完了しました。\n発注商品数: ${orderData.orderItems.length}件\n合計金額: ¥${orderData.totalAmount.toLocaleString()}`);

      // 画面をリセット
      container.querySelector('#store-select').value = '';
      renderOrderTable([]);

    } catch (error) {
      console.error('発注実行エラー:', error);
      showError('発注の実行に失敗しました');
    }
  });

  // 初期データ読み込み実行
  loadInitialData();
}
